/bin/bash -lc "cat > src/util/ordersApi.mjs <<'EOF'
/**
 * Normalizes the backend order-list response (ReadableOrderList, returned by
 * GET /api/v1/auth/orders as loaded by src/pages/other/RecentOrder.js) into
 * a stable shape: { orders, pages, total, onThisPage }.
 *
 * Backend fields used (defined on ReadableList / ReadableOrderList):
 *   orders        -> orders
 *   pageCount     -> pages   (number of pages)
 *   totalRecords  -> total   (total number of records)
 *   itemsOnPage   -> onThisPage (number of records on this page)
 *
 * Missing or invalid values become [] for the list and 0 for the counts.
 */

const asNumber = (value) =>
  typeof value === \"number\" && Number.isFinite(value) ? value : 0;

export function normalizeOrderList(response) {
  const data =
    response "'!== null && typeof response === "object" ? response : {};

  return {
    orders: Array.isArray(data.orders) ? data.orders : [],
    pages: asNumber(data.pageCount),
    total: asNumber(data.totalRecords),
    onThisPage: asNumber(data.itemsOnPage)
  };
}

export default normalizeOrderList;
EOF
